\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{array}
\usepackage{booktabs}
\pagestyle{empty}

% ── Dark-mode developer color palette ──
\definecolor{primary}{HTML}{0F172A}      % deep navy (title bar, stripes)
\definecolor{secondary}{HTML}{1E40AF}    % electric blue (section headers)
\definecolor{accent}{HTML}{0EA5E9}       % sky blue (accents)
\definecolor{gaincolor}{HTML}{22C55E}    % bright green (gainers)
\definecolor{losscolor}{HTML}{EF4444}    % warm red (losers)
\definecolor{bgposter}{HTML}{0F172A}     % dark background
\definecolor{cardbg}{HTML}{1E293B}       % card background (slate-800)
\definecolor{cardbg2}{HTML}{172554}      % darker blue card bg
\definecolor{cardbg3}{HTML}{0F2A1E}      % dark green card bg
\definecolor{cardbg4}{HTML}{2D1B1B}      % dark red card bg
\definecolor{textlight}{HTML}{F1F5F9}    % near-white text
\definecolor{textmid}{HTML}{94A3B8}      % muted slate text
\definecolor{statbg1}{HTML}{1E3A8A}      % Python stat bg
\definecolor{statbg2}{HTML}{14532D}      % C/C++ stat bg
\definecolor{statbg3}{HTML}{7F1D1D}      % Java stat bg
\definecolor{pythonblue}{HTML}{3B82F6}
\definecolor{cppgreen}{HTML}{10B981}
\definecolor{javared}{HTML}{F97316}
\definecolor{rowalt}{HTML}{1E293B}
\definecolor{rowhdr}{HTML}{0EA5E9}
\definecolor{ranknum}{HTML}{38BDF8}

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=28pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=18pt, right=16pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1pt, titlerule style={secondary!60},
    valign=top,
  },
  greencard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg3,
    borderline west={5pt}{0pt}{gaincolor},
    left=18pt, right=16pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{gaincolor},
    coltitle=gaincolor, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1pt, titlerule style={gaincolor!60},
    valign=top,
  },
  redcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg4,
    borderline west={5pt}{0pt}{losscolor},
    left=18pt, right=16pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{losscolor},
    coltitle=losscolor, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1pt, titlerule style={losscolor!60},
    valign=top,
  },
  bluecard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg2,
    borderline west={5pt}{0pt}{accent},
    left=18pt, right=16pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=1pt, titlerule style={accent!60},
    valign=top,
  },
}

% ── Table helpers ──
\newcommand{\gain}[1]{{\color{gaincolor}\bfseries$\uparrow$#1}}
\newcommand{\loss}[1]{{\color{losscolor}\bfseries$\downarrow$#1}}
\newcommand{\neutral}[1]{{\color{textmid}#1}}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=2mm},
]

% ══════════════════════════════════════════
%  TITLE BAR
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  borderline south={4pt}{0pt}{secondary},
  left=40pt, right=40pt, top=18pt, bottom=14pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{22}{26}\selectfont\bfseries\color{accent}\ttfamily PYPL INDEX \textperiodcentered\ APRIL 2026}\\[10pt]
  {\fontsize{72}{86}\selectfont\bfseries\color{textlight} Programming Language}\\[-4pt]
  {\fontsize{72}{86}\selectfont\bfseries\color{textlight} Popularity Index}\\[12pt]
  {\fontsize{34}{42}\selectfont\color{textmid}
    Which languages are developers actually \textit{learning} in 2026?
    \quad\textbullet\quad Based on Google Trends tutorial searches.}\\[8pt]
  {\fontsize{26}{34}\selectfont\color{accent!80}
    Source: PYPL / Google Trends, April 2026 \quad\textperiodcentered\quad CC BY 3.0}
}

% ══════════════════════════════════════════
%  STAT BANNER — 3 headline metrics
% ══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, boxrule=0pt, arc=0pt,
  borderline south={3pt}{0pt}{secondary!50},
  left=0pt, right=0pt, top=4pt, bottom=4pt,
  valign=center,
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  % Python stat
  \begin{minipage}[c]{0.31\linewidth}\centering
    \tcbox[enhanced, arc=6pt, colback=statbg1, colframe=pythonblue, boxrule=2pt,
           left=14pt, right=14pt, top=10pt, bottom=10pt, halign=center]{
      {\fontsize{22}{28}\selectfont\color{textmid}\ttfamily PYTHON \textbf{\#1}}\\[6pt]
      {\fontsize{80}{96}\selectfont\bfseries\color{pythonblue} 36.21\%}\\[4pt]
      {\fontsize{30}{36}\selectfont\color{textlight} Tutorial Search Share}\\[6pt]
      {\fontsize{34}{42}\selectfont\color{gaincolor}\bfseries $\uparrow$5.7\% YoY}
    }
  \end{minipage}\hfill
  % C/C++ stat
  \begin{minipage}[c]{0.31\linewidth}\centering
    \tcbox[enhanced, arc=6pt, colback=statbg2, colframe=gaincolor, boxrule=2pt,
           left=14pt, right=14pt, top=10pt, bottom=10pt, halign=center]{
      {\fontsize{22}{28}\selectfont\color{textmid}\ttfamily C/C++ \textbf{\#2}}\\[6pt]
      {\fontsize{80}{96}\selectfont\bfseries\color{cppgreen} 13.21\%}\\[4pt]
      {\fontsize{30}{36}\selectfont\color{textlight} Tutorial Search Share}\\[6pt]
      {\fontsize{34}{42}\selectfont\color{gaincolor}\bfseries $\uparrow$6.2\% YoY \textbf{$\star$Biggest Gain}}
    }
  \end{minipage}\hfill
  % Java stat
  \begin{minipage}[c]{0.31\linewidth}\centering
    \tcbox[enhanced, arc=6pt, colback=statbg3, colframe=losscolor, boxrule=2pt,
           left=14pt, right=14pt, top=10pt, bottom=10pt, halign=center]{
      {\fontsize{22}{28}\selectfont\color{textmid}\ttfamily JAVA \textbf{\#3}}\\[6pt]
      {\fontsize{80}{96}\selectfont\bfseries\color{javared} 10.01\%}\\[4pt]
      {\fontsize{30}{36}\selectfont\color{textlight} Tutorial Search Share}\\[6pt]
      {\fontsize{34}{42}\selectfont\color{losscolor}\bfseries $\downarrow$5.4\% YoY \textbf{Biggest Fall}}
    }
  \end{minipage}
}

% ══════════════════════════════════════════
%  COL 1 — TOP 10 RANKINGS TABLE (centerpiece)
% ══════════════════════════════════════════
\posterbox[bluecard, title={Top 10 Languages — Worldwide Rankings}
]{name=rankings, column=1, between=row7 and row18}{
  \fontsize{30}{40}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.8}
  \setlength{\tabcolsep}{10pt}
  \begin{tabular}{>{\color{ranknum}\bfseries\fontsize{34}{42}\selectfont}c
                  >{\bfseries}l
                  >{\fontsize{32}{40}\selectfont}r
                  >{\fontsize{30}{38}\selectfont}r}
    \rowcolor{secondary!60}
    \multicolumn{1}{c}{\color{textlight}\bfseries\fontsize{28}{34}\selectfont\#} &
    \color{textlight}\bfseries\fontsize{28}{34}\selectfont Language &
    \color{textlight}\bfseries\fontsize{28}{34}\selectfont Share &
    \color{textlight}\bfseries\fontsize{28}{34}\selectfont 1-Yr Trend \\
    \rowcolor{statbg1!80}
    1 & {\color{pythonblue}Python} & 36.21\% & \gain{5.7\%} \\
    \rowcolor{statbg2!80}
    2 & {\color{cppgreen}C/C++} & 13.21\% & \gain{6.2\%} \\
    \rowcolor{statbg3!80}
    3 & {\color{javared}Java} & 10.01\% & \loss{5.4\%} \\
    \rowcolor{rowalt}
    4 & R & 6.17\% & \gain{1.6\%} \\
    \rowcolor{primary!60}
    5 & JavaScript & 5.07\% & \loss{3.0\%} \\
    \rowcolor{rowalt}
    6 & Swift & 3.15\% & \gain{0.8\%} \\
    \rowcolor{primary!60}
    7 & C\# & 3.00\% & \loss{3.0\%} \\
    \rowcolor{rowalt}
    8 & Rust & 2.98\% & \neutral{$\approx$0} \\
    \rowcolor{primary!60}
    9 & PHP & 2.96\% & \loss{0.7\%} \\
    \rowcolor{rowalt}
    10 & Objective-C & 2.57\% & \neutral{$\approx$0} \\
  \end{tabular}
  \vspace{8pt}

  \colorbox{secondary!25}{\parbox{0.93\linewidth}{
    \vspace{4pt}
    \fontsize{28}{36}\selectfont\color{textmid}
    \textbf{\color{accent}Note:} Python alone accounts for over \textbf{\color{pythonblue}one-third}
    of all programming tutorial searches — nearly \textbf{\color{pythonblue}triple}
    the share of its nearest rival.
    \vspace{4pt}
  }}
}

\posterbox[darkcard, title={30 Languages Tracked}
]{name=langcount, column=1, between=row18 and bottom}{
  \fontsize{30}{40}\selectfont\color{textmid}
  Covering mainstream to niche — from Python to Zig.
  All shares normalized to 100\% and smoothed over a 6-month window.
}

% ══════════════════════════════════════════
%  COL 2 — GAINERS & LOSERS + 5-YEAR TRENDS
% ══════════════════════════════════════════
\posterbox[greencard, title={Biggest Gainers (1-Year)}
]{name=gainers, column=2, between=row7 and row12}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item {\color{cppgreen}\bfseries C/C++} \hfill \gain{+6.2 pts}\\
          {\color{textmid}\fontsize{28}{36}\selectfont Surged to \#2 — largest 1-yr jump of any language}
    \item {\color{pythonblue}\bfseries Python} \hfill \gain{+5.7 pts}\\
          {\color{textmid}\fontsize{28}{36}\selectfont Dominance deepens — now at 36.21\%}
    \item {\color{gaincolor}\bfseries R} \hfill \gain{+1.6 pts}\\
          {\color{textmid}\fontsize{28}{36}\selectfont Data-science demand continues rising}
    \item {\color{gaincolor}\bfseries Swift} \hfill \gain{+0.8 pts}\\
          {\color{textmid}\fontsize{28}{36}\selectfont Steady Apple ecosystem growth}
  \end{itemize}
}

\posterbox[redcard, title={Biggest Losers (1-Year)}
]{name=losers, column=2, between=row12 and row17}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item {\color{javared}\bfseries Java} \hfill \loss{$-$5.4 pts}\\
          {\color{textmid}\fontsize{28}{36}\selectfont Steepest single-year fall in PYPL history}
    \item {\color{losscolor}\bfseries JavaScript} \hfill \loss{$-$3.0 pts}\\
          {\color{textmid}\fontsize{28}{36}\selectfont Under pressure from TypeScript migration}
    \item {\color{losscolor}\bfseries C\#} \hfill \loss{$-$3.0 pts}\\
          {\color{textmid}\fontsize{28}{36}\selectfont Enterprise mindshare eroding}
    \item {\color{losscolor}\bfseries Go} \hfill \loss{$-$1.3 pts}\\
          {\color{textmid}\fontsize{28}{36}\selectfont Surprising decline despite cloud-native use}
  \end{itemize}
}

\posterbox[bluecard, title={5-Year Trend Spotlight}
]{name=fiveyear, column=2, between=row17 and bottom}{
  \fontsize{30}{40}\selectfont

  \colorbox{statbg2}{\parbox{0.93\linewidth}{
    \vspace{6pt}\fontsize{32}{42}\selectfont
    {\color{cppgreen}\bfseries C/C++} \quad
    {\color{gaincolor}\bfseries\fontsize{46}{56}\selectfont $\uparrow$7.0\%} \quad
    {\color{textlight} 5-year gain — \#1 long-term riser}
    \vspace{6pt}
  }}
  \vspace{8pt}

  \colorbox{statbg3}{\parbox{0.93\linewidth}{
    \vspace{6pt}\fontsize{32}{42}\selectfont
    {\color{javared}\bfseries Java} \quad
    {\color{losscolor}\bfseries\fontsize{46}{56}\selectfont $\downarrow$7.0\%} \quad
    {\color{textlight} 5-year decline — \#1 long-term faller}
    \vspace{6pt}
  }}
  \vspace{8pt}

  \fontsize{28}{36}\selectfont\color{textmid}
  Python has solidified its \#1 position across the entire 5-year window,
  with no credible challenger emerging.
}

% ══════════════════════════════════════════
%  COL 3 — LANGUAGES TO WATCH + METHODOLOGY + TAKEAWAYS
% ══════════════════════════════════════════
\posterbox[darkcard, title={Languages to Watch}
]{name=emerging, column=3, between=row7 and row14}{
  \fontsize{30}{40}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.7}
  \setlength{\tabcolsep}{8pt}
  \begin{tabular}{>{\bfseries}l r r >{\fontsize{26}{34}\selectfont\color{textmid}}l}
    \rowcolor{secondary!50}
    \color{textlight}\bfseries Language &
    \color{textlight}\bfseries Share &
    \color{textlight}\bfseries Trend &
    \color{textlight}\bfseries Note \\
    {\color{gaincolor}Ada} & 2.51\% & \gain{1.1\%} & Safety-critical engineering \\
    \rowcolor{rowalt}
    {\color{gaincolor}Julia} & 0.73\% & \gain{0.4\%} & Scientific computing rise \\
    {\color{gaincolor}Kotlin} & 0.90\% & \loss{0.9\%} & Declining despite Android \\
    \rowcolor{rowalt}
    {\color{textmid}Rust} & 2.98\% & \neutral{$\approx$0\%} & Stable, no explosive growth \\
    {\color{losscolor}Go} & 0.71\% & \loss{1.3\%} & Surprising cloud-native drop \\
    \rowcolor{rowalt}
    {\color{textmid}Zig} & 0.24\% & \neutral{$\approx$0\%} & Niche but stable systems \\
  \end{tabular}
  \vspace{10pt}

  \colorbox{statbg2!80}{\parbox{0.93\linewidth}{
    \vspace{4pt}\fontsize{28}{36}\selectfont\color{gaincolor}\bfseries
    Ada: \color{textlight} Safety-critical domains driving resurgence — aerospace,
    automotive, defense.
    \vspace{4pt}
  }}
}

\posterbox[darkcard, title={How PYPL Works}
]{name=method, column=3, between=row14 and row18}{
  \fontsize{30}{38}\selectfont\color{textmid}
  \begin{itemize}[itemsep=10pt]
    \item Measures \textbf{\color{accent}tutorial search frequency} on Google Trends
    \item \textbf{\color{accent}Leading indicator} — captures learning intent, not page counts
    \item Normalized relative to Java tutorials each month, summed to 100\%
    \item \textbf{\color{accent}6-month smoothing} window to reduce noise
    \item Unlike TIOBE (counts web pages), PYPL reflects \textbf{\color{accent}what devs are actively learning}
  \end{itemize}
}

\posterbox[
  enhanced, arc=4pt, boxrule=0pt, colback=secondary,
  borderline west={6pt}{0pt}{accent},
  left=18pt, right=16pt, top=10pt, bottom=10pt,
  fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{textlight},
  coltitle=textlight, colbacktitle=primary,
  toptitle=8pt, bottomtitle=8pt,
  titlerule=1pt, titlerule style={accent!80},
  valign=top,
  title={Key Takeaways}
]{name=takeaways, column=3, between=row18 and bottom}{
  \fontsize{30}{40}\selectfont\color{textlight}
  \begin{enumerate}[itemsep=12pt]
    \item {\color{pythonblue}\bfseries Python unchallenged} — 36.21\%, growing. No rival in sight.
    \item {\color{cppgreen}\bfseries C/C++ breakout story} — largest gain both 1-year (+6.2\%) and 5-year (+7.0\%).
    \item {\color{javared}\bfseries Java's slide continues} — down 5.4 pts in one year, 7.0 pts over five.
    \item {\color{losscolor}\bfseries JS \& C\# under pressure} — each losing 3.0 pts year-over-year.
    \item {\color{gaincolor}\bfseries R \& Ada quietly rising} — data science and safety-critical demand.
  \end{enumerate}
}

\end{tcbposter}
\end{document}

